"use strict";
(function(){
const $=e=>document.getElementById(e);
const qs=(s,sc=document)=>sc.querySelector(s);
const qsa=(s,sc=document)=>Array.from(sc.querySelectorAll(s));
const state={jobs:[],charts:{},progressTimer:null,network:null,files:[]};
function setStatus(status,text){const badge=$("statusBadge");badge.classList.remove("status-pending","status-running","status-completed","status-failed");if(status==="pending")badge.classList.add("status-pending");if(status==="running")badge.classList.add("status-running");if(status==="completed")badge.classList.add("status-completed");if(status==="failed")badge.classList.add("status-failed");badge.textContent=text}
function resetResults(){clearInterval(state.progressTimer);state.progressTimer=null;setStatus("pending","⏳ Várakozás");$("progressText").textContent="0%";$("progressFill").style.width="0%";$("currentStep").textContent="Inicializálás...";$("metricsGrid").innerHTML="";$("reportContent").innerHTML="";$("reportSection").style.display="none";$("sourcesSection").style.display="none"}
function renderJobCounters(){const total=state.jobs.length;const running=state.jobs.filter(j=>j.status==="running").length;const done=state.jobs.filter(j=>j.status==="completed").length;$("totalJobs").textContent=String(total);$("runningJobs").textContent=String(running);$("completedJobs").textContent=String(done)}
function renderJobsList(){const c=$("jobsList");if(state.jobs.length===0){c.innerHTML='<div class="empty-state"><div style="font-size: 2rem;">📭</div><div style="font-size: 0.85rem;">Még nincs kutatás</div></div>';return}c.innerHTML="";state.jobs.slice().reverse().forEach(job=>{const d=document.createElement("div");d.className="job-item";d.innerHTML='<div class="job-title"></div><div class="job-meta"><span></span><span></span></div>';qs(".job-title",d).textContent=job.title;const meta=qs(".job-meta",d);meta.children[0].textContent=new Date(job.created).toLocaleString();meta.children[1].textContent=job.status==="running"?"Folyamatban":"Kész";d.onclick=()=>selectJob(job.id);c.appendChild(d)})}
function selectJob(id){const job=state.jobs.find(j=>j.id===id);if(!job)return;$("resultsPanel").style.display="block";$("reportSection").style.display=job.reportHtml?"block":"none";$("sourcesSection").style.display=job.sourcesHtml?"block":"none";$("reportContent").innerHTML=job.reportHtml||"";$("sourcesSection").innerHTML=job.sourcesHtml||"";setStatus(job.status,job.status==="running"?"⚡ Fut":"✅ Kész");$("progressText").textContent=job.progressText||"0%";$("progressFill").style.width=job.progressWidth||"0%";$("currentStep").textContent=job.currentStep||"Inicializálás...";updateCharts(job.metrics||null)}
function addJob(title){const job={id:crypto.randomUUID(),title,created:Date.now(),status:"running",progressText:"0%",progressWidth:"0%",currentStep:"Inicializálás...",metrics:null,reportHtml:"",sourcesHtml:""};state.jobs.push(job);renderJobCounters();renderJobsList();return job}
function completeJob(job){job.status="completed";job.progressText="100%";job.progressWidth="100%";job.currentStep="Kész";renderJobCounters();renderJobsList()}
function updateProgress(job,percent,step){job.progressText=percent+"%";job.progressWidth=percent+"%";job.currentStep=step;$("progressText").textContent=job.progressText;$("progressFill").style.width=job.progressWidth;$("currentStep").textContent=job.currentStep}
function metricsTemplate(metrics){const items=[{label:"Feldolgozott források",value:metrics?.sources??0},{label:"Talált entitások",value:metrics?.entities??0},{label:"Releváns találatok",value:metrics?.relevant??0},{label:"Átlagos megbízhatóság",value:(metrics?.reliability??0)+"%"}];return items.map(i=>'<div class="metric-card"><div class="metric-value">'+i.value+'</div><div class="metric-label">'+i.label+"</div></div>").join("")}
